param([string]$LoginPath='upvan3306-backup')

# Read-only inventory only. No INSERT, UPDATE, DELETE, DDL, or gate changes.
$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest
$database='up_van_booking_test';$hostName='127.0.0.1';$port=3306
$uuid='77218fbd-d66d-11f1-9a0a-5c2886f057d5'
$backupRoot='C:\Users\User\upvan-reset-preflight-6426fe5fd923434981a7d23c9710de4f'
$expectedBase='7b11ba53b6d6799f93f46b4ddfabf455165c7bae063e0afffcb6ab49119ec54b'
$expectedView='04e37e4a73fc653692eeb249567834d9e8072a28d90c9225a16bd373c8d0c06d'
$mysqlBin='C:\Program Files\MySQL\MySQL Server 8.4\bin';$mysql=Join-Path $mysqlBin 'mysql.exe'
if($LoginPath -cne 'upvan3306-backup'){throw 'Only approved backup Login Path is accepted.'}
if(!(Test-Path -LiteralPath $mysql -PathType Leaf)){throw 'Pinned MySQL 8.4 client is missing.'}
if(!(Test-Path -LiteralPath (Join-Path $env:APPDATA 'MySQL\.mylogin.cnf') -PathType Leaf)){throw 'MySQL Login Path file is missing.'}
function Invoke-ReadSql([string]$Sql){
    $args=@("--login-path=$LoginPath",'--protocol=TCP',"--host=$hostName","--port=$port","--database=$database",'--default-character-set=utf8mb4','--batch','--raw','--binary-mode','--skip-column-names','--skip-reconnect')
    $psi=[Diagnostics.ProcessStartInfo]::new();$psi.FileName=$mysql;$psi.Arguments=$args -join ' ';$psi.WorkingDirectory=$mysqlBin;$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.RedirectStandardInput=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true
    $p=[Diagnostics.Process]::new();$p.StartInfo=$psi
    try{[void]$p.Start();$out=$p.StandardOutput.ReadToEndAsync();$err=$p.StandardError.ReadToEndAsync();$bytes=[Text.Encoding]::UTF8.GetBytes($Sql.TrimEnd()+";`n");$p.StandardInput.BaseStream.Write($bytes,0,$bytes.Length);$p.StandardInput.Close();$p.WaitForExit();$stdout=$out.GetAwaiter().GetResult();$stderr=$err.GetAwaiter().GetResult();if($p.ExitCode -ne 0){throw "Read-only query failed exit=$($p.ExitCode): $($stderr.Trim())"};if([string]::IsNullOrWhiteSpace($stdout)){return [string[]]@()};return [string[]]($stdout.TrimEnd("`r","`n") -split '\r?\n')}finally{$p.Dispose()}
}
function Assert-Exact([string]$Label,[string[]]$Actual,[string[]]$Expected){if(($Actual -join "`n") -cne ($Expected -join "`n")){throw "$Label mismatch; dry run stopped."}}
$backupFiles=@(@{Path=(Join-Path $backupRoot 'up_van_booking_test_base_tables.sql');Hash=$expectedBase;Label='Base tables'},@{Path=(Join-Path $backupRoot 'calendar_events_view_restore.sql');Hash=$expectedView;Label='Calendar view'})
foreach($f in $backupFiles){if(!(Test-Path -LiteralPath $f.Path -PathType Leaf)){throw "$($f.Label) backup missing."};$hash=(Get-FileHash -LiteralPath $f.Path -Algorithm SHA256).Hash.ToLowerInvariant();if($hash -cne $f.Hash){throw "$($f.Label) backup SHA-256 mismatch."};if((Get-Item -LiteralPath $f.Path).Length -le 0){throw "$($f.Label) backup is empty."};Write-Output "BACKUP_$($f.Label.Replace(' ','_'))=PASS bytes=$((Get-Item -LiteralPath $f.Path).Length) sha256=$hash"}
$identity=@(Invoke-ReadSql 'SELECT @@hostname,@@port,@@server_uuid,DATABASE(),VERSION(),CURRENT_USER()');if($identity.Count -ne 1){throw 'Identity query row count mismatch.'};$id=@($identity[0] -split "`t");if($id.Count -ne 6 -or $id[1] -cne '3306' -or $id[2] -cne $uuid -or $id[3] -cne $database -or $id[4] -notmatch '^8\.4\.' -or !$id[5]){throw 'MySQL identity mismatch; dry run stopped.'};Write-Output "IDENTITY=PASS host=$($id[0]) port=$($id[1]) uuid=$($id[2]) database=$($id[3]) version=$($id[4]) backup_account=$($id[5])"
$requests=@(Invoke-ReadSql "SELECT CONCAT(id,CHAR(9),workflow_status,CHAR(9),version) FROM booking_requests WHERE deleted_at IS NULL ORDER BY id");$totals=@(Invoke-ReadSql "SELECT CONCAT(COUNT(*),CHAR(9),COALESCE(SUM(deleted_at IS NULL),0),CHAR(9),COALESCE(SUM(deleted_at IS NOT NULL),0)) FROM booking_requests");if($totals.Count -ne 1){throw 'Request totals query failed.'};$t=@($totals[0] -split "`t");if($t.Count -ne 3 -or $t[0] -ne '8' -or $t[1] -ne '6' -or $t[2] -ne '2'){throw "Request counts changed from expected 8/6/2; found $($totals[0]); stop."}
Write-Output "REQUEST_TOTALS total=$($t[0]) active=$($t[1]) soft_deleted=$($t[2])";Write-Output 'RESET_CANDIDATES id workflow_status version:';foreach($row in $requests){Write-Output $row};if($requests.Count -ne 6){throw 'Expected six active candidates; stop.'}
$assignments=@(Invoke-ReadSql "SELECT CONCAT(booking_request_id,CHAR(9),status,CHAR(9),COUNT(*)) FROM vehicle_assignments GROUP BY booking_request_id,status ORDER BY booking_request_id,status");Write-Output 'ASSIGNMENTS_BY_BOOKING_STATUS:';foreach($a in $assignments){Write-Output $a};$blocking=@($assignments|Where-Object{($_ -split "`t")[1] -in @('active','completed')});if($blocking.Count -gt 0){throw 'Active/completed assignments found; reset dry run stopped.'}
$calendar=@(Invoke-ReadSql "SELECT CONCAT(booking_request_id,CHAR(9),assignment_status,CHAR(9),workflow_status) FROM calendar_events ORDER BY booking_request_id");Write-Output "CALENDAR_EVENTS count=$($calendar.Count)";foreach($c in $calendar){Write-Output $c}
$deps=@(Invoke-ReadSql "SELECT CONCAT(TABLE_SCHEMA,CHAR(9),TABLE_NAME) FROM information_schema.VIEW_TABLE_USAGE WHERE VIEW_SCHEMA='up_van_booking_test' AND VIEW_NAME='calendar_events' ORDER BY TABLE_SCHEMA,TABLE_NAME");if($deps.Count -ne 2){throw 'Calendar view dependency count mismatch.'};$depTables=@($deps|ForEach-Object{$f=@($_ -split "`t");if($f.Count -ne 2 -or $f[0] -cne $database){throw 'Calendar view dependency identity mismatch.'};$f[1]}|Sort-Object -Unique);if(($depTables -join ',') -cne 'booking_requests,vehicle_assignments'){throw 'Calendar view dependency list mismatch.'};Write-Output "VIEW_DEPENDENCIES=PASS tables=$($depTables -join ',')"
$preserved=@(Invoke-ReadSql "SELECT CONCAT(b.id,CHAR(9),COALESCE((SELECT COUNT(*) FROM approval_decisions d WHERE d.booking_request_id=b.id),0),CHAR(9),COALESCE((SELECT COUNT(*) FROM booking_notifications n WHERE n.booking_request_id=b.id),0),CHAR(9),COALESCE((SELECT COUNT(*) FROM booking_status_history h WHERE h.booking_request_id=b.id),0)) FROM booking_requests b WHERE b.deleted_at IS NULL ORDER BY b.id");Write-Output 'PRESERVED_RECORD_COUNTS id decisions notifications history:';foreach($p in $preserved){Write-Output $p}
$grants=@(Invoke-ReadSql "SHOW GRANTS FOR 'up_van_auth_test'@'127.0.0.1'");Write-Output 'RUNTIME_ACCOUNT_GRANTS (read-only; reset is not executed by this script):';foreach($g in $grants){Write-Output $g}
Write-Output 'RESET_DRY_RUN=PASS read_only=true';Write-Output 'APPLY=NOT_IMPLEMENTED; this script cannot modify data.'
